CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx2b869d29c6$doc_the_social_security_act_2075_2018_2075_the_social_security_act_20$CODEx2b869d29c6$,$CODEx96c2279bed$The Social Security Act, 2075 (2018)$CODEx96c2279bed$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2075,2018,9,$CODEx386de3574c$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommision.gov.np\nThe Social Security Act, 2075 (2018)\nDate of Authentication:\n2075.06.02 (18 September 2018)\nAct Number 19 of the year 2075\nAn Act Made to Provide for Social Security\nPreamble:\nWhereas, it is expedient to make necessary provisions on the protection of the\nright to social security of the indigent citizens, incapacitated and helpless citizens,\nhelpless single women, citizens with disabilities, children, citizens who are unable to take\ncare themselves and citizens belonging to the tribes on the verge of extinction, in\naccordance with the Constitution;\nNow, therefore, be it enacted by the Federal Parliament.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Chapter-1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement: (1) This Act may be cited as the \"Social Security", "content": "Act, 2075 (2018).”\n(2) This Act shall commence immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or the context otherwise requires, in this Act, -", "content": "(a) \"Incapacitated and helpless\" means those persons who are indigent\neconomically and incapacitated to make labor physically or mentally, and\nhave no family members for maintaining and taking care of them.\n(b) \"Citizens with disabilities\" means those persons referred to in Section 8,\nwho have long-term physical, mental, intellectual or sensory disabilities or\nfunctional impairments or existing barriers that may hinder their full and\neffective participation in social life on an equal basis with others.\n(c) \"Helpless single women” means the women referred to in Section 7, who\nhave no basis, income source or property for making the life, are\nincapacitated and helpless having income less than that specified by the\nGovernment of Nepal by publishing a notice in the Nepal Gazette.\n(d) \"Indigent\" means those persons who earn income less than that specified\nby the Government of Nepal by publishing a notice in the Nepal Gazette.\n(e) \"Citizens unable to take care themselves” means the persons who are certified\nby the medical doctor that they are in a condition of being unable to take care\n1\nwww.lawcommision.gov.np\nthemselves due to suffering from diseases such as Alzheimer's, Parkinson's,\nspinal cord injury, brain hemorrhage, mental retardation, paralysis, sickle cell\nanemia, mental unsoundness and autism.\n(f) \"Prescribed\" or \"as prescribed\" means prescribed or as prescribed in the\nrules framed under this Act.\n(g) “Tribes on the verge of extinction” means the tribes referred to in the\nSchedule.\n(h) “Persons entitled to social security” means the Nepali citizens who are\nentitled to social security allowance pursuant to this Act.\n(i) “Social security” means cash, allowance or support to be provided to the\ncitizens entitled to social security pursuant to this Act.\n(i) “Local Level” means the Rural Municipality or Municipality.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "Entitlement to social security: (1) The following Nepali citizens shall have the", "content": "right to get the social security allowance:\n(a) Senior citizens,\n(b) Indigent,\n(c) Incapacitated and helpless persons,\n(d) Helpless single women,\n(e) Citizens with disabilities,\n(f) Children,\n(g) Citizens unable to take care themselves.\n(2) The allowances to be distributed pursuant to sub-section (1) shall be\ndistributed in the name of social security.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Senior citizen allowance: (1) The Dalit and single women senior citizens, after", "content": "completing the age of sixty years, and other senior citizens, after completing the age of\nseventy years, shall get the senior citizen allowance as prescribed by the Government\nof Nepal, as the social security allowance.\n(2) Notwithstanding anything contained in sub-section (1), the Government of\nNepal may, by specifying any certain area, provide such allowance also the senior\ncitizens who are living in such area and have not completed the age referred to in sub-\nsection (1).\n2\nwww.lawcommision.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Destitute citizen allowance: The destitute citizens shall get the destitute citizen", "content": "allowance in a sum as specified by the Government of Nepal as the social security\nallowance as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Incapacitated and helpless allowance: The citizens who incapacitated and helpless", "content": "shall get the incapacitated and helpless allowance in a sum as specified by the\nGovernment of Nepal as the social security allowance as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Helpless single woman allowance: (1) The following helpless single women who have", "content": "completed the age of sixty years shall get the helpless single woman allowance in a sum\nas specified by the Government of Nepal as the social security allowance as prescribed:\n(a) Who have not had second marriage after getting divorced,\n(b) Widows,\n(c) Who are living upon getting legal separation,\n(d) Unmarried.\n(2) Notwithstanding anything contained in sub-section (1), even the helpless\nsingle women referred to in clauses (a), (b), and (c) of sub-section (1), who have not\ncompleted the age of sixty years, have no source of income to make a living, have\nincome less than that fixed by the Government of Nepal and cannot labor shall get such\na facility.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Disability allowance: The citizens with total disability shall get the disability", "content": "allowance in a sum specified by the Government of Nepal as the social security\nallowance.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Child nutrition allowance: (1) The children who are extremely destitute, on the verge", "content": "of extinction and such children who have not completed the age of five years as\nspecified by the Government of Nepal shall get the child nutrition allowance in a sum\nspecified by the Government of Nepal as the social security allowance.\n(2) The procedures for providing the child nutrition allowance pursuant to sub-\nsection (1) to the children shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "Tribe on the verge of extinction allowance: (1) The citizens belonging to the tribes", "content": "on the verge of extinction shall get the social security allowance specified by the\nGovernment of Nepal.\n(2) The procedures for providing the allowance to the tribes on the verge of\nextinction pursuant to sub-section (1) shall be as prescribed.\n3\nwww.lawcommision.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Care allowance for those who are unable to take care of themselves: (1) The citizens", "content": "who are unable to take care of themselves shall get the social security allowance\nspecified by the Government of Nepal.\n(2) The procedures for providing the allowance to the citizens who are unable\nto take care of themselves pursuant to sub-section (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Application to be made: (1) A person who is entitled to get the social security", "content": "allowance pursuant to Section 3 shall make an application to the Local Level concerned\nto get the social security allowance referred to in this Act.\nProvided that, on behalf of the person who cannot make application himself or\nherself, his or her guardian curator or caretaker may make such application.\n(2) While making an application pursuant to sub-section (1) for the social\nsecurity allowance receivable by the children pursuant to Section 9, evidence of the\nrecord of birth registration shall also be submitted.\n(3) In cases where an application is received pursuant to sub-section (1) or (2),\nthe Local Level shall make decision by taking necessary action within seven days.\n(4) While taking action pursuant to sub-section (3), if it appears that the\napplicant is not entitled to the social security allowance, information thereof in writing,\nsetting out the reason, shall be given to the applicant.\n(5) The format of application referred to in sub-section (1) and documents to be\nattached therewith shall be as prescribed.\n(6) A person who does not wish to receive the social security allowance pursuant\nto this Section shall make a self-declaration that he or she will not receive the social\nsecurity allowance and give information to the concerned Local Level.\n(7) In cases where any citizen does not wish to receive the social security\nallowance pursuant to sub-section (6), the concerned Local Level shall honor such a\nperson by maintaining the records thereof.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Not to get double social security: (1) In cases where any citizen is entitled to more", "content": "than one kind of social security allowances pursuant to Section 3 of this Act, he or she\nshall get only one social security allowance chosen by him or her.\n(2) In cases where any citizen is entitled to the same kind of facility pursuant to\nthis Act and the prevailing law, he or she may get only one of the facilities chosen by\nhim or her.\n4\nwww.lawcommision.gov.np\n(3) Notwithstanding anything contained in sub-sections (1) and (2), the children\nwho have got allowances under the other prevailing laws may also get the allowance\nreferred to in Section 9.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "To get facilities under the prevailing law: (1) Notwithstanding anything contained in", "content": "Section 13, this Act shall not bar the person who is entitled to the social security\nallowance pursuant to this Act from receiving other kinds of social security to be\nreceivable under the prevailing law.\n(2) Except in cases where the families of the martyrs who have sacrificed their\nlives, of the persons subjected to enforced disappearance, warriors of democracy,\npersons with disabilities, and those injured and victims, in the course of popular\nmovement, armed conflict and revolution having taken place for a progressive\ndemocratic change in Nepal have got the social security pursuant to the prevailing law,\nthey shall get the security or honor as prescribed.\n(3) The Government of Nepal may adopt a unified system on the provision of\nthe social security allowance to be provided pursuant to this Act and other social\nsecurity to be provided pursuant to the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Not being entitled to social security allowance: The following persons shall not get", "content": "the social security allowance referred to in this Act:\n(a) The persons who are appointed, elected, nominated for any government\nor public offices,\n(b) The persons who are receiving pension from a government fund,\n(c) The persons who are regularly receiving remuneration, pension,\nretirement facility and other incentives in any other manner.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "16", "title": "Identity card: (1) The concerned Local Level shall give identity cards in the prescribed", "content": "format to the persons entitled to get the social security allowance pursuant to this Act.\n(2) The identity of the guardian, curator or caretaker of the person entitled to\nget the social security allowance shall also be set out in the identity card to be given\npursuant to sub-section (1).\n(3) The Local Level shall review, and update the records of, the identity cards\nrelating to disabilities every year.\n(4) Other provisions relating to the identity cards to be given pursuant to sub-\nsection (1) shall be as prescribed.\n(5) The citizens who have not got the identity cards pursuant to sub-section (1)\nshall not get the social security allowance.\n5\nwww.lawcommision.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Distribution of social security allowance: (1) The Local Level shall distribute the", "content": "social security allowance on the basis of the identity cards referred to in Section 16.\n(2) The process and modes for the distribution of social security by the Local\nLevel pursuant to sub-section (1) shall be as prescribed.\n(3) The payment of the social security allowance shall be made only through\nthe banking system in such area and from such date as specified by the Government of\nNepal by publishing a notice in the Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "To maintain records: (1) The Local Level shall maintain records of social security", "content": "distributed pursuant to this Act, in the prescribed format.\n(2) The Local Level shall send the description of the distribution of social\nsecurity to the concerned body of the Government of Nepal in such format and with\nsuch period as prescribed.\n(3) Other provisions relating to the management of records referred to in sub-\nsection (1) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "19", "title": "To delete the name of person entitled to social security: (1) The Local Level shall", "content": "delete the name of a person who has got the social security allowance from its records\nin any of the following conditions:\n(a) Where the person entitled to the social security allowance has migrated\nto elsewhere,\n(b) Where the helpless single woman has got married,\n(c) Where the person has been disqualified to get social security pursuant to\nthis Act,\n(d) Where the person has died,\n(e) In such other conditions as prescribed.\n(2) In cases where the person entitled to the social security allowance\npursuant to clause (a) of sub-section (1) is to migrate to another place, the Local Level\nconcerned shall mention that description in the identity card.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "To manage budget by the Government of Nepal: (1) The Government of Nepal shall", "content": "have the obligation of the social security allowance pursuant to this Act.\n(2) Additional social security allowance shall not be so distributed by the\nProvincial and Local Governments under the respective headings that it is in\noverlapping (duplication) with the social security allowance to be distributed by the\nGovernment of Nepal.\n6\nwww.lawcommision.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-3", "title": "Chapter-3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "21", "title": "Offences and punishment: (1) In cases where a person does any of the following acts,", "content": "he or she shall be deemed to have committed the offence under this Act:\n(a) Taking the social security allowance by lying the description,\n(b) Taking the social security allowance contrary to this Act or the Rules\nframed under this Act,\n(c) Misusing the social security allowance received by any person or using\nit against his or her interest, by his or her guardian, curator or caretaker\nor other person,\n(d) Misusing of the social security allowance by the official who distributes\nthe social security allowance,\n(e) Submitting a false description or making a false recommendation.\n(2) In cases where a person commits any of the offences referred to in\nclauses (a), (b), (c) and (e) of sub-section (1), the person shall be liable to a fine that is\nequal to the claimed amount, after recovering the amount taken by him or her who\ncommits such offence.\n(3) In cases where a person commits the offence referred to in clause (d) or\nmakes a false recommendation under clause (e) of sub-section (1), the concerned\nofficial shall be punished under the prevailing law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "To make complaint: Any person may make a complaint on the offence under this Act", "content": "to the Judicial Committee of the concerned Local Level.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "To try cases: (1) The Judicial Committee of the Local Level concerned shall try and", "content": "settle the cases other than that referred to in clause (d) of sub-section (1) of Section 21\nunder this Act.\n(2) The Judicial Committee shall try and settle the case referred to in sub-section\n(1)) within one hundred and twenty days from the date of its filing.\n(3) Notwithstanding anything contained in sub-sections (1) and (2), in cases\nwhere a complaint related to the offence referred to in clause (d) of sub-section (1) of\nSection 21 is made, such a complaint shall be sent to the body concerned for necessary\naction.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Appeal: A person who is not satisfied with the decision made by the Judicial", "content": "Committee pursuant to Section 23 may make an appeal to the District Court within\nthirty-five days from the date of receipt of information of such decision.\n7\nwww.lawcommision.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Punish imposable under the prevailing law: In cases where any act deemed to be an", "content": "offence under this Act is also deemed to be an offence under the prevailing law, nothing\ncontained in this Act shall be deemed to bar from instituting and proceeding the case\nunder the prevailing law on such an offence.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "26", "title": "Provision relating to monitoring: The provisions relating to the management of", "content": "records of the persons who get social security and monitoring of the distribution of\nallowances shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Power to establish care center: The Government of Nepal, Provincial Government or", "content": "Local Level may establish and operate care centers, as prescribed, for taking care of the\norphan children, incapacitated and helpless persons, persons with disabilities and senior\ncitizens.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "To make report: Every Local Level shall provide description of the distributed social", "content": "security allowance to the Government of Nepal and the concerned Provincial\nGovernment on a four-monthly basis.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Power to frame Rules: The Government of Nepal may frame necessary Rules in order", "content": "to implement this Act.\nProvided that nothing herein contain shall prevent the provision of such social\nsecurity allowances as being distributed by the Government of Nepal until the Rules\nhave been framed under this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "To make directives and procedures: The Ministry of the Government of Nepal", "content": "looking after the matters relating to federal affairs may make necessary directives and\nprocedures, subject to this Act and the Rules framed under this Act, on the distribution\nof the social security allowance.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Power to alter the Schedule: The Government of Nepal may make necessary", "content": "alteration in the Schedule, by publishing a notice in the Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "This Act to prevail: The matters contained herein shall be governed by this Act, and", "content": "the other matters shall be governed by the prevailing law.\n8\nwww.lawcommision.gov.np\nSchedule\nRelating to clause (g) of Section 2\nTribes on the verge of extinction\n Kusunda\n Raute\n Hayu\n Kisan\n Meche\n Bankariya\n Surel\n Raji\n Lopcha\n Kuswadiya (Pattharkatta, Silkat, Kushbadhiya and Kuchbadhiya)\n9", "children": []}]}]$CODEx386de3574c$::jsonb,$CODEx886600ec37$The-Social-Security-Act-2075-2018.x71134.pdf$CODEx886600ec37$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
